using System.Collections.Generic;using System.ComponentModel;using System.Runtime.CompilerServices;
namespace PhotoBooth.Customer.UI.Mvvm { public abstract class ObservableObject:INotifyPropertyChanged { public event PropertyChangedEventHandler PropertyChanged;protected bool Set<T>(ref T f,T v,[CallerMemberName]string n=null){if(EqualityComparer<T>.Default.Equals(f,v))return false;f=v;PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(n));return true;}protected void Raise([CallerMemberName]string n=null)=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(n));} }
